import React, { useState, useEffect } from 'react';
import axios from 'axios';

function App() {
  const [message, setMessage] = useState('');

  useEffect(() => {
    axios.get('http://localhost:8000/')
      .then(res => setMessage(res.data.message));
  }, []);

  return (
    <div className="App">
      <h1>Agent Lucky App</h1>
      <p>{message}</p>
    </div>
  );
}

export default App;
